13	export interface ToolItem {
14	  key: string;
15	  num?: string;
16	  action: string;
17	  name: string;
18	  text: (fighterName: string, target?: Target) => string;
19	  needsFighter: boolean;
20	  /** Shift-modified: plain key = head, Shift+key = body. Read via e.code + e.shiftKey. */
21	  hasTarget?: boolean;
22	  /** Kicks already encode target in the action name — no modifier needed. */
23	  fixedTarget?: Target;
24	}
25	
26	export interface ToolGroup {
27	  group: string;
28	  note?: string;
29	  items: ToolItem[];
30	}
31	
32	// Shared by every hand strike + elbow so the description always reflects the
33	// real target instead of a value baked in per-action (right_hook used to be
34	// hardcoded "to the body" regardless of where it actually landed).
35	//
36	// jab/cross are lead/rear-relative (boxing terms), not absolute-handed —
37	// a southpaw's jab is thrown with their right hand. Hooks/uppercuts stay
38	// absolute left/right: that's what you can directly see (which arm moved)
39	// without first judging stance, and it's lossless either way since both
40	// hands collapse to the same family (`hook`/`uppercut`) at export time.
41	const HAND_STRIKE_NAMES: Record<string, string> = {
42	  jab: 'jab',
43	  cross: 'cross',
44	  left_hook: 'left hook',
45	  right_hook: 'right hook',
46	  left_uppercut: 'left uppercut',
47	  right_uppercut: 'right uppercut',
48	  elbow: 'elbow',
49	};
50	
51	function handStrikeText(action: string, fighterName: string, target: Target = 'head'): string {
52	  return `${fighterName} ${HAND_STRIKE_NAMES[action]} to the ${target}`;
53	}
