111	// Landed-vs-missed is deferred (MVP target is "count strikes thrown"), so every
112	// strike logs success=null — outcome unknown, not a claim that it landed.
113	// `knockdown` and `takedown_landed` are the exceptions: neither is a default
114	// outcome of pressing the key (unlike a strike, which the palette has no
115	// landed/missed toggle for), so a logged one genuinely happened.
116	const SUCCESS_TRUE_ACTIONS = new Set(['knockdown', 'takedown_landed']);
117	
118	export function successForAction(action: string): boolean | null {
119	  return SUCCESS_TRUE_ACTIONS.has(action) ? true : null;
120	}
