122	export function categoryForAction(action: string | null): EventCat {
123	  if (!action) return 'state';
124	  if (action === 'fight_end' || action === 'submission_attempt') return 'event';
125	  if (action.startsWith('takedown_')) return 'grapple';
126	  if (action.startsWith('state_')) return 'state';
127	  if (action.startsWith('round_')) return 'round';
128	  return 'strike';
