159	export function matchFilter(cat: EventCat, filter: string): boolean {
160	  if (filter === 'all') return true;
161	  if (filter === 'grapple') return cat === 'grapple' || cat === 'event';
162	  if (filter === 'state') return cat === 'state' || cat === 'round';
163	  return cat === filter;
