188	/** Frame (1-based) → "m:ss" clock, matching the currentFrame = floor(t*fps)+1 contract. */
189	export function formatFrameClock(frame: number, fps: number): string {
190	  const seconds = Math.max(0, (frame - 1) / fps);
191	  const m = Math.floor(seconds / 60);
192	  const s = Math.floor(seconds % 60);
193	  return `${m}:${String(s).padStart(2, '0')}`;
194	}
